SELECT id, kod1, uzel1, kod2, uzel2, cnt, date_calc, procent, mag, name_tt, name_tt2, diameterCondit, len, firstPICdateHP, lastTransDate, date_osv, srok, srok2, v19, v20, n_cap, n_def, v23, v24, v25, v26, v27, name_org, koef_povr, srok2_ball, VnesniiVid2, SostOborudovania2, Kategorii2, VnesnKorrozia2, VnunrenKorrozia2, SostKonstrukz2, 

  IIF(procent < 20, 'secondary', 
  IIF(procent < 40, 'success', 
  IIF(procent < 60, 'warning', 
  IIF(procent < 80, 'orange', 
  'danger')))) AS _rowVariant

FROM ( SELECT pps.id, ec1.name AS kod1, n1.externalNodeName AS uzel1, ec2.name AS kod2, n2.externalNodeName AS uzel2, _T2.cnt, calc.DateRascheta AS date_calc, IIF(mag.naimenovanie_magistrali IS NULL, rs.naimenovanie_uchastka_rs,mag.naimenovanie_magistrali) AS mag, tt.name AS name_tt, tt2.name AS name_tt2, hps1.diameterCondit, IIF(_T2.lenP >= _T2.lenO, IIF (_T2.lenP > 0, _T2.lenP, 1), _T2.lenO) AS len, hps1.firstPICdateHP, hps1.lastTransDate, sh1.data_osmotra AS date_osv, 25 AS srok, DATEDIFF(YEAR,hps1.firstPICdateHP,(calc.DateRascheta)) AS srok2, f1.name AS v19, f3.name AS v20, IIF(cap1.n_defekt IS NULL, 0, cap1.n_defekt) AS n_cap, IIF(df1.n_defekt IS NULL, 0, df1.n_defekt) AS n_def, f2.name AS v23, ((IIF(cap1.n_defekt IS NULL, 0, cap1.n_defekt))+(IIF(df1.n_defekt IS NULL, 0, df1.n_defekt)))*100/(IIF(_T2.lenP >= _T2.lenO, IIF (_T2.lenP > 0, _T2.lenP, 1), _T2.lenO)) AS v24, f7.name AS v25, f8.name AS v26, buildingConstrStates.name AS v27, org.name AS name_org, IIF((DATEDIFF(YEAR,hps1.firstPICdateHP,(calc.DateRascheta))) <= 7, 1, IIF((DATEDIFF(YEAR,hps1.firstPICdateHP,(calc.DateRascheta))) <= 15, 2, IIF((DATEDIFF(YEAR,hps1.firstPICdateHP,(calc.DateRascheta))) < 20, 3, IIF((DATEDIFF(YEAR,hps1.firstPICdateHP,(calc.DateRascheta))) < 25, 4, 5)))) AS srok2_ball, IIF((((IIF(cap1.n_defekt IS NULL, 0, cap1.n_defekt))+(IIF(df1.n_defekt IS NULL, 0, df1.n_defekt)))*100/(IIF(_T2.lenP >= _T2.lenO, IIF (_T2.lenP > 0, _T2.lenP, 1), _T2.lenO))) < 1, 1, IIF( (((IIF(cap1.n_defekt IS NULL, 0, cap1.n_defekt))+(IIF(df1.n_defekt IS NULL, 0, df1.n_defekt)))*100/(IIF(_T2.lenP >= _T2.lenO, IIF (_T2.lenP > 0, _T2.lenP, 1), _T2.lenO))) < 2, 2, IIF( (((IIF(cap1.n_defekt IS NULL, 0, cap1.n_defekt))+(IIF(df1.n_defekt IS NULL, 0, df1.n_defekt)))*100/(IIF(_T2.lenP >= _T2.lenO, IIF (_T2.lenP > 0, _T2.lenP, 1), _T2.lenO))) < 4, 3, IIF((((IIF(cap1.n_defekt IS NULL, 0, cap1.n_defekt))+(IIF(df1.n_defekt IS NULL, 0, df1.n_defekt)))*100/(IIF(_T2.lenP >= _T2.lenO, IIF (_T2.lenP > 0, _T2.lenP, 1), _T2.lenO))) < 5, 4, 5)))) AS koef_povr, IIF(pps.VnesniiVid IS NULL, 0, pps.VnesniiVid) AS VnesniiVid2, IIF(pps.SostOborudovania IS NULL, 0, pps.SostOborudovania) AS SostOborudovania2, IIF(pps.Kategorii IS NULL, 0, pps.Kategorii) AS Kategorii2, IIF(pps.VnesnKorrozia IS NULL, 0, pps.VnesnKorrozia) AS VnesnKorrozia2, IIF(pps.VnunrenKorrozia IS NULL, 0, pps.VnunrenKorrozia) AS VnunrenKorrozia2, IIF(pps.SostKonstrukz IS NULL, 0, pps.SostKonstrukz) AS SostKonstrukz2, ((IIF((DATEDIFF(YEAR,hps1.firstPICdateHP,(calc.DateRascheta))) <= 7, 1, IIF((DATEDIFF(YEAR,hps1.firstPICdateHP,(calc.DateRascheta))) <= 15, 2, IIF((DATEDIFF(YEAR,hps1.firstPICdateHP,(calc.DateRascheta))) < 20, 3, IIF((DATEDIFF(YEAR,hps1.firstPICdateHP,(calc.DateRascheta))) < 25, 4, 5)))))*0.15+ (IIF((((IIF(cap1.n_defekt IS NULL, 0, cap1.n_defekt))+(IIF(df1.n_defekt IS NULL, 0, df1.n_defekt)))*100/(IIF(_T2.lenP >= _T2.lenO, IIF (_T2.lenP > 0, _T2.lenP, 1), _T2.lenO))) < 1, 1, IIF( (((IIF(cap1.n_defekt IS NULL, 0, cap1.n_defekt))+(IIF(df1.n_defekt IS NULL, 0, df1.n_defekt)))*100/(IIF(_T2.lenP >= _T2.lenO, IIF (_T2.lenP > 0, _T2.lenP, 1), _T2.lenO))) < 2, 2, IIF( (((IIF(cap1.n_defekt IS NULL, 0, cap1.n_defekt))+(IIF(df1.n_defekt IS NULL, 0, df1.n_defekt)))*100/(IIF(_T2.lenP >= _T2.lenO, IIF (_T2.lenP > 0, _T2.lenP, 1), _T2.lenO))) < 4, 3, IIF((((IIF(cap1.n_defekt IS NULL, 0, cap1.n_defekt))+(IIF(df1.n_defekt IS NULL, 0, df1.n_defekt)))*100/(IIF(_T2.lenP >= _T2.lenO, IIF (_T2.lenP > 0, _T2.lenP, 1), _T2.lenO))) < 5, 4, 5)))))*0.2+ (IIF(pps.VnesniiVid IS NULL, 0, pps.VnesniiVid))*0.05+ (IIF(pps.SostOborudovania IS NULL, 0, pps.SostOborudovania))*0.2+ (IIF(pps.Kategorii IS NULL, 0, pps.Kategorii))*0.1+ (IIF(pps.VnesnKorrozia IS NULL, 0, pps.VnesnKorrozia))*0.1+ (IIF(pps.VnunrenKorrozia IS NULL, 0, pps.VnunrenKorrozia))*0.1+ (IIF(pps.SostKonstrukz IS NULL, 0, pps.SostKonstrukz))*0.1)*20 AS procent FROM heatPipeSections hps1 LEFT OUTER JOIN heatPipeSections hps2 ON hps1.pipeSectionID = hps2.pipeSectionID AND NOT hps1.pipeSectionID IS NULL AND NOT hps2.pipeSectionID IS NULL AND (hps1.pipeSectLength < hps2.pipeSectLength OR (hps1.pipeSectLength = hps2.pipeSectLength AND hps1.id < hps2.id)) JOIN ( SELECT hps2.pipeSectionID, COUNT(hps2.id) cnt, SUM(IIF(l.externalSignLineID IN (1,2,4), hps2.pipeSectLength, 0)) AS lenP, SUM(IIF(l.externalSignLineID IN (1,3,5), hps2.pipeSectLength, 0)) AS lenO FROM heatPipeSections hps2 JOIN linesobj l ON l.id=hps2.lineID GROUP BY hps2.pipeSectionID ) _T2 ON _T2.pipeSectionID = hps1.pipeSectionID JOIN pipeSections pps ON pps.id=hps1.pipeSectionID JOIN nodes n1 ON n1.id=pps.nodeID1 JOIN nodes n2 ON n2.id=pps.nodeID2 LEFT JOIN externalCodes ec1 on ec1.id = n1.externalCodeID LEFT JOIN externalCodes ec2 on ec2.id = n2.externalCodeID LEFT JOIN tubingTypes tt on tt.id = hps1.tubingTypeID JOIN linesobj l2 ON l2.id=hps1.lineID LEFT JOIN organizations org ON org.id=l2.organizationID LEFT JOIN tubeTypes tt2 on tt2.id = hps1.tubeTypeID LEFT JOIN magistrali mag ON mag.id=hps1.magistral LEFT JOIN uchastok_rs rs ON rs.id=hps1.distSite LEFT JOIN ( SELECT hps1.pipeSectionID, MAX(s1.data_osmotra) AS data_osmotra, COUNT(s1.id) AS s1id FROM shurf2 s1 LEFT JOIN linesobj l1 ON l1.id=s1.lineID LEFT JOIN heatPipeSections hps1 ON hps1.lineID=l1.id GROUP BY hps1.pipeSectionID ) sh1 ON sh1.pipeSectionID=pps.id LEFT JOIN ( SELECT hps1.pipeSectionID, MAX(s1.data_osmotra) AS data_osmotra, COUNT(s1.id) AS n_defekt FROM defekt2 s1 LEFT JOIN linesobj l1 ON l1.id=s1.lineID LEFT JOIN heatPipeSections hps1 ON hps1.lineID=l1.id GROUP BY hps1.pipeSectionID ) df1 ON df1.pipeSectionID=pps.id LEFT JOIN ( SELECT hps1.pipeSectionID, MAX(s1.data_osmotra) AS data_osmotra, COUNT(s1.id) AS n_defekt FROM capital2 s1 LEFT JOIN linesobj l1 ON l1.id=s1.lineID LEFT JOIN heatPipeSections hps1 ON hps1.lineID=l1.id GROUP BY hps1.pipeSectionID ) cap1 ON cap1.pipeSectionID=pps.id LEFT JOIN iznos iz ON iz.pipeSectionID=pps.id LEFT JOIN CALCULATION_IZNOS calc ON calc.id=iz.calculationID LEFT JOIN faktIznos_1_vneshnii_vid f1 ON f1.id=pps.VnesniiVid LEFT JOIN faktIznos_3_sost_obor f3 ON f3.id=pps.SostOborudovania LEFT JOIN faktIznos_2_kat_narush f2 ON f2.id=pps.Kategorii LEFT JOIN faktRiska_7_vneshkorroz f7 ON f7.id=pps.VnesnKorrozia LEFT JOIN faktRiska_8_vnutkorroz f8 ON f8.id=pps.VnunrenKorrozia LEFT JOIN buildingConstrStates ON buildingConstrStates.id=pps.SostKonstrukz WHERE hps2.id IS NULL ) _TTTTT ORDER BY id;
